prime[0] = prime[1] = False
p = 2
while p * p <= N:
    if prime[p]:
        for x in range(p * p, N + 1, p):
            prime[x] = False
    p += 1
prefix = [0] * (N + 1)
for x in range(1, N + 1):
    prefix[x] = prefix[x - 1] + int(prime[x])
