n, m = map(int, input().split())
grid = [list(input().strip()) for _ in range(n)]
answer = 0
for r in range(n):
    for c in range(m):
        if grid[r][c] != '1':
            continue
        answer += 1
        grid[r][c] = '0'
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m:
                    if grid[nx][ny] == '1':
                        grid[nx][ny] = '0'
                        stack.append((nx, ny))
print(answer)

